import {implicitMarkup} from './gear.js';
import {icon} from './icons.js';
import {AFFIXES,ITEM_GRADES,affixText,affixGrade,affixSlots,itemLabel,uniqueDescription} from './loot.js';
import {CRAFT_OPERATIONS,craftCost,craftEligibility} from './crafting.js';
import {ESSENCE_RECOVERY,ESSENCE_SUCCESS,MAX_ESSENCE_STACKS,essenceCount,essenceEligibility} from './essences.js';
let craftSelected='',essenceSelected='',essenceGrade='all',essenceKind='all';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const selectCraftItem=id=>{craftSelected=id;};
export const selectEssence=id=>{essenceSelected=id;};
export const selectEssenceFilter=(type,value)=>{
 if(type==='grade'&&(value==='all'||ITEM_GRADES.includes(value)))essenceGrade=value;
 if(type==='kind'&&['all','prefix','suffix','compatible'].includes(value))essenceKind=value;
};
export const craftTargets=s=>[...Object.values(s.equipment).filter(Boolean),...s.inventory];
export function essencePouch(s){
 const count=essenceCount(s),stacks=[...(s.essences||[])];
 stacks.sort((a,b)=>affixGrade(b.affix)-affixGrade(a.affix)||b.count-a.count||a.affix.id.localeCompare(b.affix.id));
 return `<section class="panel secondary-panel essence-pouch"><div class="view-section-title"><div><span class="eyebrow">RECOVERED MODIFIERS</span><h2>Essence pouch <span class="capacity">${count}</span></h2><p>${stacks.length} / ${MAX_ESSENCE_STACKS} stacks · identical modifiers stack together</p></div><button class="button" data-view="forge">${icon('hammer')} Craft with essences</button></div><div class="essence-grade-counts">${ITEM_GRADES.map((g,i)=>`<span class="grade-${i}"><b>${g}</b><small>${stacks.filter(e=>affixGrade(e.affix)===i).reduce((n,e)=>n+e.count,0)}</small></span>`).join('')}</div>${stacks.length?`<div class="essence-stack-list">${stacks.map(e=>{const label=`${ITEM_GRADES[affixGrade(e.affix)]} · ${affixText(e.affix)} <small>${AFFIXES[e.affix.id].kind}</small>`;return `<div class="essence-stack-row grade-${affixGrade(e.affix)}"><span class="stack-mod">${ITEM_GRADES[affixGrade(e.affix)]} · ${affixText(e.affix)} <small>${AFFIXES[e.affix.id].kind}</small></span><span class="stack-count">×${e.count}</span><button class="essence-discard" data-discard-essence="${esc(e.id)}" data-essence-label="${esc(affixText(e.affix))}" aria-label="Discard ${esc(affixText(e.affix))} essences">${icon('close')}</button></div>`;}).join('')}</div>`:'<p class="bag-empty">No essences recovered yet. Salvage equipment to capture its modifiers.</p>'}<p class="inventory-note">Each essence holds one explicit modifier with its exact grade and value. Use them at the forge, or discard any stack to free pouch space. Salvage spare equipment to find more; the loot filter can ignore lower grades.</p></section>`;
}
export function craftingPanel(s){
 const items=craftTargets(s),item=items.find(i=>i.id===craftSelected)||items[0]||null;
 if(item)craftSelected=item.id;
 const essences=[...(s.essences||[])].sort((a,b)=>affixGrade(b.affix)-affixGrade(a.affix)||AFFIXES[a.affix.id].kind.localeCompare(AFFIXES[b.affix.id].kind)||a.affix.id.localeCompare(b.affix.id));
 const filtered=essences.filter(e=>{
  const gradeMatches=essenceGrade==='all'||ITEM_GRADES[affixGrade(e.affix)]===essenceGrade;
  const kindMatches=essenceKind==='all'||(essenceKind==='compatible'?!essenceEligibility(item,e):AFFIXES[e.affix.id].kind===essenceKind);
  return gradeMatches&&kindMatches;
 });
 const selected=filtered.find(e=>e.id===essenceSelected)||filtered.find(e=>!essenceEligibility(item,e))||filtered[0]||essences.find(e=>e.id===essenceSelected)||essences[0];
 if(selected)essenceSelected=selected.id;
 const reason=essenceEligibility(item,selected),grade=selected?affixGrade(selected.affix):0;
 return `<section class="panel secondary-panel craft-panel"><div class="view-section-title"><div><h2>The crafting bench</h2><p>Grade follows the strongest modifier. Up to three prefixes and three suffixes.</p></div><button class="text-button" data-action="mod-dictionary">${icon('book')} Modifier dictionary</button></div>
 <div class="craft-target"><label for="craft-item">Target equipment</label><select id="craft-item">${items.map(i=>`<option value="${esc(i.id)}" ${i.id===item?.id?'selected':''}>${itemLabel(i)} · ${esc(i.name)} · i${i.itemLevel}</option>`).join('')}</select><span class="craft-summary">${item?`${affixSlots(item).prefix} / 3 prefixes · ${affixSlots(item).suffix} / 3 suffixes`: 'No equipment available'}</span></div>
 ${item?`<div class="craft-preview">${implicitMarkup(item)}${item.unique?`<div class="unique-power"><strong>${icon('star')} Permanent unique implicit</strong><p>${esc(uniqueDescription(item))}</p></div>`:''}<ul>${item.affixes.length?item.affixes.map(a=>`<li><span>${affixText(a)} <small>${AFFIXES[a.id].kind}</small></span><small class="grade-${affixGrade(a)}">${ITEM_GRADES[affixGrade(a)]} · ${a.min}–${a.max}</small></li>`).join(''):'<li class="empty">No explicit modifiers · grade D</li>'}</ul></div>`:''}
 <h3 class="craft-section-heading">Orb crafting</h3><p class="craft-guidance">Consume one orb and the shown gold cost. Only Divine Orbs can change implicit rolls; unique powers cannot be removed.</p><div class="craft-orbs">${Object.entries(CRAFT_OPERATIONS).map(([id,op])=>{
  const cost=item?craftCost(op,item):null,stock=s.orbs?.[id]||0,blocked=craftEligibility(id,item)||(!stock?'No orbs available':s.gold<cost.gold?'Not enough gold':'');
  return `<button class="craft-orb ${id}" data-craft="${id}" ${blocked?'disabled':''} title="${esc(blocked||op.flavor)}">${icon(op.icon)}<span><strong>${op.name}<b>×${stock}</b></strong><small class="orb-rule">${op.flavor}</small><small>${cost?cost.gold+' gold':'Choose an item'}${blocked?' · '+esc(blocked):''}</small></span></button>`;
 }).join('')}</div>
 <section class="essence-bench"><div class="view-section-title"><div><h3>Essence crafting</h3><p>${essenceCount(s)} essences · select a modifier card to inspect and transfer it</p></div><button class="text-button" data-action="loot-filter">Salvage filter ${icon('chevron')}</button></div>
 <div class="essence-browser" aria-label="Essence pouch"><div class="essence-browser-toolbar"><label class="essence-search">${icon('compass')}<span class="sr-only">Search essences</span><input id="essence-search" type="search" placeholder="Search modifiers" autocomplete="off"></label><div class="essence-kind-tabs" role="group" aria-label="Essence type">${[['all','All'],['prefix','Prefixes'],['suffix','Suffixes'],['compatible','Compatible']].map(([id,label])=>`<button class="filter-button ${essenceKind===id?'selected':''}" data-essence-kind="${id}" aria-pressed="${essenceKind===id}">${label}</button>`).join('')}</div></div>
 <div class="essence-grade-tabs" role="group" aria-label="Essence grade"><button class="filter-button ${essenceGrade==='all'?'selected':''}" data-essence-grade="all" aria-pressed="${essenceGrade==='all'}">All <span>${essences.length}</span></button>${ITEM_GRADES.map((label,index)=>`<button class="filter-button grade-${index} ${essenceGrade===label?'selected':''}" data-essence-grade="${label}" aria-pressed="${essenceGrade===label}">${label} <span>${essences.filter(e=>affixGrade(e.affix)===index).length}</span></button>`).join('')}</div>
 <div class="essence-card-grid">${filtered.length?filtered.map(e=>{const g=affixGrade(e.affix),def=AFFIXES[e.affix.id],why=essenceEligibility(item,e),active=e.id===selected?.id;return `<button class="essence-choice grade-${g} ${active?'selected':''} ${why?'incompatible':''}" data-essence="${esc(e.id)}" data-essence-search="${esc(`${def.name} ${def.label} ${def.kind} ${ITEM_GRADES[g]}`.toLowerCase())}" aria-pressed="${active}" title="${esc(why||`Select ${def.name}`)}"><span class="essence-gem">${icon(def.kind==='prefix'?'up':'sparkles')}<b>${ITEM_GRADES[g]}</b></span><span class="essence-choice-copy"><strong>${esc(def.name)}</strong><small>${affixText(e.affix)}</small><em>${def.kind} · ${Math.round(ESSENCE_SUCCESS[g]*100)}% success</em></span><span class="essence-choice-count">×${e.count}</span>${why?`<i title="${esc(why)}">${icon('lock')}</i>`:''}</button>`;}).join(''):`<div class="essence-browser-empty">${icon('gem')}<strong>${essences.length?'No essences match these filters.':'Your essence pouch is empty.'}</strong><span>${essences.length?'Try another grade or type.':'Salvage modified gear for a chance to recover each explicit modifier.'}</span></div>`}</div></div>
 ${selected?`<div class="essence-preview grade-${grade}"><div class="essence-preview-heading"><div><span>${ITEM_GRADES[grade]} ${AFFIXES[selected.affix.id].kind} essence</span><strong>${affixText(selected.affix)}</strong></div><b>×${selected.count}</b></div><div class="essence-chance"><span><b>${Math.round(ESSENCE_SUCCESS[grade]*100)}%</b> chance to apply</span><i><b style="width:${ESSENCE_SUCCESS[grade]*100}%"></b></i></div><small>${reason||((item.affixes||[]).some(a=>a.id===selected.affix.id)?'Replaces the weaker modifier of this family.':'Fills one open '+AFFIXES[selected.affix.id].kind+' slot.')}</small><div class="essence-preview-actions"><button class="text-button danger-text" data-discard-essence-one="${esc(selected.id)}">Discard one</button><button class="text-button danger-text" data-discard-essence="${esc(selected.id)}" data-essence-label="${esc(affixText(selected.affix))}">Discard stack</button></div></div>`:''}
 <p class="craft-guidance">A valid attempt consumes one essence, including on failure. Failure leaves the item unchanged. Replace a weaker modifier of the same family, or use an open slot. The essence carries its exact grade and value; no item-level requirement applies.</p><button class="button gold-button essence-apply" data-apply-essence="${esc(selected?.id||'')}" ${reason?'disabled':''}>${icon('hammer')} ${reason?'Cannot apply selected essence':'Apply essence · '+Math.round(ESSENCE_SUCCESS[grade]*100)+'% success'}</button></section></section>`;
}
